import {useEffect,useState} from 'react';
import {Alert,Image,Pressable,StyleSheet,Text,TextInput,View} from '@/platform/react-native';
import {Ionicons} from '@/platform/icons';
import {router,useLocalSearchParams} from '@/router';
import {useQueryClient} from '@tanstack/react-query';
import {Screen,useAppTheme} from '@/components/UI';
import {api} from '@/lib/api';
import {normalizeInviteCode,savePendingCommunityInvite} from '@/lib/communityInvite';
import {useAuth} from '@/store/auth';

export default function JoinCommunity(){
 const params=useLocalSearchParams<{code?:string}>();const{palette}=useAppTheme();const{accessToken}=useAuth();const qc=useQueryClient();
 const[code,setCode]=useState(normalizeInviteCode(params.code||''));const[community,setCommunity]=useState<any>(null);const[loading,setLoading]=useState(false);const[error,setError]=useState('');
 useEffect(()=>{if(params.code){const normalized=normalizeInviteCode(params.code);setCode(normalized);void lookup(normalized)}},[params.code]);
 async function lookup(value=code){const normalized=normalizeInviteCode(value);setError('');setCommunity(null);if(normalized.length<4){setError('Enter a valid community invite code.');return}try{setLoading(true);const r=await api.get(`/communities/invite/${encodeURIComponent(normalized)}`);setCommunity(r.data)}catch(e:any){setError(e.response?.data?.error||'This invite code is invalid or has expired.')}finally{setLoading(false)}}
 async function join(){if(!community)return;if(!accessToken){await savePendingCommunityInvite(code);Alert.alert('Sign in to join','Sign in or create an account, then CDA Connect will join you to this community automatically.',[{text:'Cancel',style:'cancel'},{text:'Register',onPress:()=>router.push('/(auth)/onboarding' as any)},{text:'Log in',onPress:()=>router.push('/(auth)/login' as any)}]);return}try{setLoading(true);const r=await api.post('/communities/join',{joinCode:code});await qc.invalidateQueries({queryKey:['communities']});router.replace(`/community/${r.data.Id}` as any)}catch(e:any){setError(e.response?.data?.error||'Unable to join this community.')}finally{setLoading(false)}}
 return <Screen scroll contentStyle={s.page}><View style={[s.card,{backgroundColor:palette.surface,borderColor:palette.border}]}><View style={[s.icon,{backgroundColor:palette.primarySoft}]}><Ionicons name="enter-outline" size={34} color={palette.primary}/></View><Text style={[s.title,{color:palette.text}]}>Join with invite code</Text><Text style={[s.copy,{color:palette.muted}]}>Enter the code shared by a community administrator.</Text><TextInput accessibilityLabel="Community invite code" value={code} onChangeText={v=>{setCode(normalizeInviteCode(v));setCommunity(null);setError('')}} autoCapitalize="characters" autoCorrect={false} placeholder="ENTER CODE" placeholderTextColor={palette.muted} style={[s.input,{color:palette.text,backgroundColor:palette.background,borderColor:palette.border}]}/><Pressable disabled={loading} onPress={()=>lookup()} style={[s.primary,{backgroundColor:palette.primary}]}><Ionicons name="search-outline" size={20} color="#fff"/><Text style={s.primaryText}>{loading?'Checking…':'Find community'}</Text></Pressable>{error?<Text accessibilityRole="alert" style={[s.error,{color:palette.danger}]}>{error}</Text>:null}</View>{community?<View style={[s.card,{backgroundColor:palette.surface,borderColor:palette.border}]}>{community.BannerUrl?<Image source={{uri:community.BannerUrl}} style={s.banner}/>:null}<View style={s.communityHead}>{community.LogoUrl?<Image source={{uri:community.LogoUrl}} style={s.logo}/>:<View style={[s.icon,{backgroundColor:palette.primarySoft}]}><Ionicons name="home-outline" size={30} color={palette.primary}/></View>}<View style={{flex:1}}><Text style={[s.name,{color:palette.text}]}>{community.Name}</Text><Text style={{color:palette.muted}}>{Number(community.MemberCount||0).toLocaleString()} members · {community.IsPrivate?'Private':'Public'}</Text></View></View><Text style={[s.description,{color:palette.text}]}>{community.Description||'Join this community on CDA Connect.'}</Text><Text style={[s.location,{color:palette.muted}]}>{[community.City,community.Country].filter(Boolean).join(', ')}</Text><View style={s.actions}><Pressable onPress={()=>router.canGoBack()?router.back():router.replace('/(tabs)/communities')} style={[s.cancel,{borderColor:palette.primary}]}><Text style={{color:palette.primary,fontWeight:'900'}}>Cancel</Text></Pressable><Pressable disabled={loading} onPress={join} style={[s.join,{backgroundColor:palette.primary}]}><Text style={s.primaryText}>Join</Text></Pressable></View></View>:null}</Screen>
}
const s=StyleSheet.create({page:{maxWidth:620,paddingBottom:110},card:{borderWidth:1,borderRadius:20,padding:20,marginBottom:16,overflow:'hidden'},icon:{width:62,height:62,borderRadius:18,alignItems:'center',justifyContent:'center'},title:{fontSize:25,fontWeight:'900',marginTop:16},copy:{fontSize:15,lineHeight:22,marginTop:5},input:{height:62,borderWidth:1.5,borderRadius:14,paddingHorizontal:18,fontSize:20,fontWeight:'900',letterSpacing:3,marginTop:20},primary:{height:56,borderRadius:14,flexDirection:'row',gap:9,alignItems:'center',justifyContent:'center',marginTop:13},primaryText:{color:'#fff',fontSize:16,fontWeight:'900'},error:{fontWeight:'800',marginTop:13},banner:{height:150,width:'100%',borderRadius:14,marginBottom:16},communityHead:{flexDirection:'row',alignItems:'center',gap:13},logo:{width:62,height:62,borderRadius:18},name:{fontSize:22,fontWeight:'900'},description:{fontSize:15,lineHeight:22,marginTop:16},location:{marginTop:8,fontWeight:'700'},actions:{flexDirection:'row',gap:12,marginTop:20},cancel:{flex:1,height:54,borderWidth:1.5,borderRadius:13,alignItems:'center',justifyContent:'center'},join:{flex:1,height:54,borderRadius:13,alignItems:'center',justifyContent:'center'}});
